import { Link } from "react-router-dom";
import NotesEtoiles from "../commun/NotesEtoiles";
import { usePanier } from "../../hooks/usePanier";

export default function CarteProduit({ produit }) {
  const { ajouterAuPanier } = usePanier();

  return (
    <div className="card">
      <Link to={`/produit/${produit.id}`}>
        <img src={produit.image} style={{ height: "150px" }} />
      </Link>

      <h4>{produit.title}</h4>

      <NotesEtoiles note={produit.rating?.rate} />

      <p>{produit.price} €</p>

      <button onClick={() => ajouterAuPanier(produit)}>
        Ajouter
      </button>
    </div>
  );
}
